settings.custom_css:
.bx:hover,
.bx.is-active{
    border-radius: 29px;
    border: 1px solid #181B31;
    background: var(--Bg-Card-1, #0C0D17);
}

.bx{
    border-radius: 29px;
    border: 1px solid #181B3100;
    background: var(--Bg-Card-1, #0C0D1700);
}

.inner{
    height: 40px !important;
    overflow: hidden;
    transition: height .7s ease;
}

/* Quando .bx sofre hover OU está ativo */
.bx:hover .inner,
.bx.is-active .inner{
    height: 150px !important;
}

.num{
    width: 50px !important;
    height: 50px !important;
    border-radius: 16px;
    border: 1px solid var(--Line-1, #181B31);
}

.num .elementor-heading-title{
    display:flex;
    justify-content: center;
    top: 50%;
    left: 50%;
    right:0;
    position: absolute;
    transform: translate(-50%, -50%);
}

.num {
    z-index: 1;
}

.bx .num:before {
    content: "";
    position: absolute;
    z-index: 10;
    border-radius: 16px;
    pointer-events: none;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    padding: 1px;
    background: linear-gradient(to right, #3975FE80, transparent);
    -webkit-mask:
      linear-gradient(#fff 0 0) content-box,
      linear-gradient(#fff 0 0);
    mask:
      linear-gradient(#fff 0 0) content-box,
      linear-gradient(#fff 0 0);
    -webkit-mask-composite: xor;
    mask-composite: exclude;
    transition: 0.7s ease all;
    opacity: 0;
}

.bx:hover .num:before,
.bx.is-active .num:before{
    opacity: 1;
}

.bx:before {
    content: "";
    position: absolute;
    z-index: 10;
    border-radius: 29px;
    pointer-events: none;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    padding: 1px;
    background: linear-gradient(to right, #3975FE80, transparent);
    -webkit-mask:
      linear-gradient(#fff 0 0) content-box,
      linear-gradient(#fff 0 0);
    mask:
      linear-gradient(#fff 0 0) content-box,
      linear-gradient(#fff 0 0);
    -webkit-mask-composite: xor;
    mask-composite: exclude;
    transition: 0.7s ease all;
    opacity: 0;
}

.bx:hover:before,
.bx.is-active:before{
    opacity: 1;
}

/* MOBILE */
@media(max-width:600px){

  .bx{
    border-radius: 29px;
    border: 1px solid #181B31;
    background: var(--Bg-Card-1, #0C0D17);
  }

  .num {
    z-index: 1;
  }

  .bx .num:before {
    opacity: 1;
  }

  .bx:before {
    opacity: 1;
  }

}
